#include <iostream>
#include <vector>
#include <string>
#include <cstring>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <chrono>
#include <thread>
#include <map>

static const unsigned char INDEX_KEY[32] = {
    0x2b,0x7e,0x15,0x16,0x28,0xae,0xd2,0xa6,
    0xab,0xf7,0x15,0x88,0x09,0xcf,0x4f,0x3c,
    0x6b,0xc1,0xbe,0xe2,0x2e,0x40,0x9f,0x96,
    0xe9,0x3d,0x7e,0x11,0x73,0x93,0x17,0x2a
};

static const unsigned char HMAC_KEY[32] = {
    0xa3,0x4f,0x88,0x21,0x9c,0x67,0xd4,0x0e,
    0x5b,0x12,0xf9,0x7a,0x3c,0x85,0xe6,0x41,
    0xd7,0x2e,0x93,0x56,0x0f,0xb8,0x64,0xc1,
    0x7d,0xa0,0x4e,0x19,0x82,0xf5,0x3b,0x6c
};

struct IndexEntry {
    std::vector<unsigned char> iv;
    std::vector<unsigned char> ciphertext;
    std::vector<unsigned char> mac;
    uint32_t doc_id;
};

std::map<uint32_t, IndexEntry> g_index;

enum class DecryptStatus {
    SUCCESS,
    AUTH_ERROR
};

bool verify_mac(const std::vector<unsigned char>& iv,
                const std::vector<unsigned char>& ct,
                const std::vector<unsigned char>& mac) {
    unsigned char computed[32];
    unsigned int computed_len = 0;

    HMAC_CTX* hctx = HMAC_CTX_new();
    HMAC_Init_ex(hctx, HMAC_KEY, 32, EVP_sha256(), nullptr);
    HMAC_Update(hctx, iv.data(), iv.size());
    HMAC_Update(hctx, ct.data(), ct.size());
    HMAC_Final(hctx, computed, &computed_len);
    HMAC_CTX_free(hctx);

    if (mac.size() != 32) return false;
    return CRYPTO_memcmp(computed, mac.data(), 32) == 0;
}

DecryptStatus decrypt_entry(const IndexEntry& entry, std::string& plaintext) {
    if (!verify_mac(entry.iv, entry.ciphertext, entry.mac)) {
        return DecryptStatus::AUTH_ERROR;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return DecryptStatus::AUTH_ERROR;

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr,
                           INDEX_KEY, entry.iv.data()) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return DecryptStatus::AUTH_ERROR;
    }

    std::vector<unsigned char> outbuf(entry.ciphertext.size() + 16);
    int outlen = 0;

    if (EVP_DecryptUpdate(ctx, outbuf.data(), &outlen,
                          entry.ciphertext.data(), entry.ciphertext.size()) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return DecryptStatus::AUTH_ERROR;
    }

    int final_len = 0;
    int ret = EVP_DecryptFinal_ex(ctx, outbuf.data() + outlen, &final_len);
    EVP_CIPHER_CTX_free(ctx);

    if (ret != 1) {
        return DecryptStatus::AUTH_ERROR;
    }

    plaintext.assign(outbuf.begin(), outbuf.begin() + outlen + final_len);
    return DecryptStatus::SUCCESS;
}

void encrypt_and_store(uint32_t doc_id, const std::string& term) {
    IndexEntry entry;
    entry.doc_id = doc_id;
    entry.iv.resize(16);
    RAND_bytes(entry.iv.data(), 16);

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, INDEX_KEY, entry.iv.data());

    std::vector<unsigned char> outbuf(term.size() + 32);
    int outlen = 0;
    EVP_EncryptUpdate(ctx, outbuf.data(), &outlen,
                      (const unsigned char*)term.data(), term.size());
    int final_len = 0;
    EVP_EncryptFinal_ex(ctx, outbuf.data() + outlen, &final_len);
    EVP_CIPHER_CTX_free(ctx);

    entry.ciphertext.assign(outbuf.begin(), outbuf.begin() + outlen + final_len);

    unsigned char mac[32];
    unsigned int mac_len = 0;
    HMAC_CTX* hctx = HMAC_CTX_new();
    HMAC_Init_ex(hctx, HMAC_KEY, 32, EVP_sha256(), nullptr);
    HMAC_Update(hctx, entry.iv.data(), entry.iv.size());
    HMAC_Update(hctx, entry.ciphertext.data(), entry.ciphertext.size());
    HMAC_Final(hctx, mac, &mac_len);
    HMAC_CTX_free(hctx);
    entry.mac.assign(mac, mac + 32);

    g_index[doc_id] = entry;
}

struct SearchResponse {
    uint8_t status_code;
    uint32_t result_count;
    std::vector<uint32_t> doc_ids;
};

SearchResponse handle_search_query(const std::vector<unsigned char>& query_ct,
                                    const std::vector<unsigned char>& query_iv,
                                    const std::vector<unsigned char>& query_mac) {
    SearchResponse resp;
    resp.result_count = 0;

    IndexEntry query_entry;
    query_entry.iv = query_iv;
    query_entry.ciphertext = query_ct;
    query_entry.mac = query_mac;
    query_entry.doc_id = 0;

    std::string query_term;
    DecryptStatus ds = decrypt_entry(query_entry, query_term);

    if (ds == DecryptStatus::AUTH_ERROR) {
        resp.status_code = 0x02;
        return resp;
    }

    resp.status_code = 0x00;

    for (auto& [id, entry] : g_index) {
        std::string stored_term;
        if (decrypt_entry(entry, stored_term) == DecryptStatus::SUCCESS) {
            if (stored_term.find(query_term) != std::string::npos) {
                resp.doc_ids.push_back(id);
                resp.result_count++;
            }
        }
    }

    return resp;
}

// Read exactly len bytes; returns true only if all bytes were read.
static bool read_full(int fd, void* buf, size_t len) {
    unsigned char* p = static_cast<unsigned char*>(buf);
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, p + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return false;
        }
        if (n == 0) {
            return false; // connection closed before full data received
        }
        total += static_cast<size_t>(n);
    }
    return true;
}

void serve(int port) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 10);

    while (true) {
        int client = accept(server_fd, nullptr, nullptr);
        if (client < 0) continue;

        uint16_t ct_len = 0;
        if (!read_full(client, &ct_len, 2)) {
            close(client);
            continue;
        }
        ct_len = ntohs(ct_len);

        if (ct_len == 0 || ct_len > 4096 || ct_len % 16 != 0) {
            close(client);
            continue;
        }

        std::vector<unsigned char> iv(16);
        if (!read_full(client, iv.data(), 16)) {
            close(client);
            continue;
        }

        std::vector<unsigned char> ct(ct_len);
        if (!read_full(client, ct.data(), ct_len)) {
            close(client);
            continue;
        }

        std::vector<unsigned char> mac(32);
        if (!read_full(client, mac.data(), 32)) {
            close(client);
            continue;
        }

        auto resp = handle_search_query(ct, iv, mac);

        write(client, &resp.status_code, 1);
        uint32_t count_net = htonl(resp.result_count);
        write(client, &count_net, 4);
        for (auto id : resp.doc_ids) {
            uint32_t id_net = htonl(id);
            write(client, &id_net, 4);
        }

        close(client);
    }
}

int main() {
    encrypt_and_store(1, "confidential_merger_document");
    encrypt_and_store(2, "quarterly_earnings_report");
    encrypt_and_store(3, "employee_salary_data");
    encrypt_and_store(4, "public_press_release");

    std::cout << "Search index service starting on port 8443..." << std::endl;
    serve(8443);
    return 0;
}
